/* Pulse high-fidelity prototype. All records are illustrative and stored locally in this browser. */
const KEY='pulse-demo-v2';
const seed={role:'patient',page:'home',selected:'saira',lang:'en',reviewFilter:'all',search:'',activeTab:'week',
 patients:[
  {id:'saira',name:'Saira Khan',initials:'SK',age:42,city:'Indore',condition:'Hypertension · early pre-diabetes',doctor:'Dr. Mehta',since:'Sep 16, 2026',engagement:76,bpTarget:'< 130/80',glucoseTarget:'As set by clinician',review:'Routine follow-up',lastSeen:'Today, 7:42 AM',barrier:'Evening routine disrupted by late work days',intervention:'Moved activity goal to mornings',trend:[146,142,139,136,134,133,132],measurements:[['Oct 14, 7:42 AM','BP','132 / 84','Home BP monitor'],['Oct 13, 7:38 AM','BP','134 / 86','Home BP monitor'],['Oct 12, 8:06 AM','BP','133 / 84','Manual entry'],['Oct 11, 7:55 AM','BP','136 / 86','Home BP monitor'],['Oct 10, 8:12 AM','Glucose','112 mg/dL','Glucometer'],['Oct 10, 7:48 AM','BP','136 / 87','Home BP monitor'],['Oct 09, 7:51 AM','BP','139 / 88','Home BP monitor']],
   plan:[{id:'bp',title:'Check blood pressure',detail:'After waking · seated and rested',time:'Morning',done:true,source:'Dr. Mehta'},{id:'walk',title:'20-minute walk',detail:'Choose a time that fits your day',time:'Morning',done:false,source:'Dr. Mehta'},{id:'meal',title:'Low-salt meal choice',detail:'Keep your usual home meal; adjust salt',time:'Lunch',done:false,source:'Dr. Mehta'},{id:'sleep',title:'Wind down by 11 PM',detail:'Keep your sleep routine consistent',time:'Evening',done:false,source:'Dr. Mehta'}],devices:[{id:'bpmonitor',name:'BP monitor',type:'Blood pressure',icon:'⌁',connected:true,last:'Today, 7:42 AM'},{id:'glucose',name:'Glucometer',type:'Blood glucose',icon:'◉',connected:false,last:'Not paired'}],notes:[],appointment:'Nov 1, 2026',shared:true},
  {id:'rsharma',name:'Ravi Sharma',initials:'RS',age:51,city:'Indore',condition:'Hypertension',doctor:'Dr. Mehta',since:'Sep 29, 2026',engagement:43,bpTarget:'< 130/80',glucoseTarget:'—',review:'Review suggested',lastSeen:'3 days ago',barrier:'Has not shared yet',intervention:'No change proposed',trend:[138,140,142,145,144,147,149],measurements:[['Oct 11, 8:05 AM','BP','149 / 92','Home BP monitor'],['Oct 09, 8:17 AM','BP','147 / 91','Home BP monitor']],plan:[{id:'bp',title:'Check blood pressure',detail:'Morning measurement',time:'Morning',done:false,source:'Dr. Mehta'},{id:'walk',title:'Daily activity goal',detail:'As discussed in your visit',time:'Any time',done:true,source:'Dr. Mehta'}],devices:[{id:'bpmonitor',name:'BP monitor',type:'Blood pressure',icon:'⌁',connected:true,last:'Oct 11, 8:05 AM'}],notes:[],appointment:'Nov 8, 2026',shared:true},
  {id:'apatel',name:'Anita Patel',initials:'AP',age:46,city:'Indore',condition:'Hypertension',doctor:'Dr. Mehta',since:'Aug 25, 2026',engagement:88,bpTarget:'< 130/80',glucoseTarget:'—',review:'On track',lastSeen:'Today, 6:58 AM',barrier:'None reported',intervention:'Routine stable',trend:[139,137,136,134,132,131,129],measurements:[['Oct 14, 6:58 AM','BP','129 / 80','Home BP monitor'],['Oct 13, 7:02 AM','BP','131 / 82','Home BP monitor']],plan:[{id:'bp',title:'Check blood pressure',detail:'Before breakfast',time:'Morning',done:true,source:'Dr. Mehta'},{id:'walk',title:'30-minute walk',detail:'Brisk walk, 5 days/week',time:'Morning',done:true,source:'Dr. Mehta'}],devices:[{id:'bpmonitor',name:'BP monitor',type:'Blood pressure',icon:'⌁',connected:true,last:'Today, 6:58 AM'}],notes:[],appointment:'Oct 24, 2026',shared:true}
 ],tasks:{},lastSync:'Today, 7:42 AM',setupDone:true,settings:{notifications:true,shareTrends:true,shareContext:false,shareFamily:false,weeklySummary:true,privacyLock:true}};
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));return s?{...structuredClone(seed),...s,patients:s.patients?.length?s.patients:structuredClone(seed.patients),settings:{...seed.settings,...s.settings}}:structuredClone(seed)}catch(e){return structuredClone(seed)}}
const demoMessages={saira:[{id:'m-review-1',date:'Sep 20, 2026 · 11:15 AM',by:'Dr. Mehta',role:'doctor',kind:'review',visibility:'shared',read:false,text:'I reviewed your care plan with you at today’s visit. We’ll track your home BP readings and the daily activity goal we discussed. We can review your progress together at follow-up.'},{id:'m-patient-1',date:'Oct 06, 2026 · 8:40 PM',by:'Saira',role:'patient',kind:'message',visibility:'shared',read:true,text:'Evening walks have been difficult because I have been getting home late from work.'},{id:'m-doctor-1',date:'Oct 07, 2026 · 9:10 AM',by:'Dr. Mehta',role:'doctor',kind:'care_update',visibility:'shared',read:false,text:'Thanks for sharing that. Your activity goal stays the same. Pulse can help you try a morning time if that fits your routine. We’ll check how it is working at your next visit.'},{id:'m-review-2',date:'Oct 13, 2026 · 4:30 PM',by:'Dr. Mehta',role:'doctor',kind:'review',visibility:'shared',read:false,text:'I reviewed the home readings currently in Pulse. Please continue your existing care plan. We can discuss the trend and your questions at the scheduled follow-up.'}]};
let S=load();S.patients.forEach(p=>{if(!Array.isArray(p.messages))p.messages=structuredClone(demoMessages[p.id]||[]);p.notes=p.notes||[];const migrated=[];p.notes=p.notes.filter(n=>{if(n.by==='Patient draft'){migrated.push({id:'m-migrated-'+Date.now(),date:n.date||'Earlier',by:'Patient',role:'patient',kind:'message',visibility:'shared',read:true,text:n.text});return false}if(!n.visibility)n.visibility='careTeam';return true});p.messages.push(...migrated)});save();const app=document.getElementById('app');
function save(){localStorage.setItem(KEY,JSON.stringify(S))}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function current(){return S.patients.find(p=>p.id===S.selected)||S.patients[0]}
function go(page){S.page=page;save();render();window.scrollTo({top:0,behavior:'smooth'})}
function initials(name){return name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function percent(p=current()){return Number(p.engagement)||0}
function countLabel(n){return `${n} ${n===1?'patient':'patients'}`}
function isProvider(){return S.role==='provider'}
const patientNav=[['home','⌂','My care'],['plan','☷','Care plan'],['insights','✦','Insights'],['messages','✉','Messages & care updates'],['devices','⌁','Devices & readings'],['history','◷','Progress history'],['appointments','▦','Appointments'],['privacy','◇','Privacy & sharing']];
const providerNav=[['clinic','▦','Clinic overview'],['patients','♧','Patients'],['reviews','⚑','Attention queue'],['carebuilder','☷','Care plan builder'],['reports','▥','Outcome reports']];
function navButton([id,icon,label]){const unread=id==='messages'&&!isProvider()?(current().messages||[]).filter(m=>m.role==='doctor'&&!m.read&&m.visibility==='shared').length:0;const count=id==='reviews'?S.patients.filter(p=>p.review==='Review suggested').length:unread;const badge=count?`<span class="nav-count">${count}</span>`:'';return `<button class="${S.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}${badge}</button>`}
function render(){const p=current(),nav=isProvider()?providerNav:patientNav;if(!isProvider()&&S.page==='messages'){(p.messages||[]).forEach(m=>{if(m.role==='doctor'&&m.visibility==='shared')m.read=true});save()}app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">♥</div><div>Pulse<small>Care continuity</small></div></div><div class="workspace-label">${isProvider()?'Clinic workspace':'Patient app'}</div><div class="nav">${nav.map(navButton).join('')}</div>${isProvider()?`<div class="workspace-label">Selected patient</div><button class="nav" style="border:0;background:none;padding:0" data-page="patients"><div class="patient-cell" style="padding:7px 10px"><span class="avatar">${p.initials}</span><span><b>${esc(p.name)}</b><small>${esc(p.condition)}</small></span></div></button>`:''}<div class="sidebar-bottom"><div class="demo-card"><b>Prototype workspace</b><p>Demo records stay in this browser. Device readings are simulated; no clinical records are sent to a server.</p></div><div class="user-mini"><div class="avatar">${isProvider()?'DM':p.initials}</div><div><b>${isProvider()?'Dr. Mehta':esc(p.name)}</b><small>${isProvider()?'Care team · Indore':'Patient · Indore'}</small></div><button class="button link small" data-page="${isProvider()?'reports':'privacy'}" aria-label="Settings">⚙</button></div></div></aside><section class="workspace"><header class="topbar"><div class="crumb"><button class="button link small mobile-menu" data-action="menu">☰</button><span>${isProvider()?'Swasthya Clinic · Indore':'Pulse · My care'}</span><span style="padding:0 6px">/</span><b style="color:var(--ink)">${esc(pageTitle())}</b></div><div class="top-actions"><span class="status-strip"><i class="dot" style="color:#69b489"></i> Demo mode</span><div class="role-switch"><button class="${!isProvider()?'active':''}" data-role="patient">Patient</button><button class="${isProvider()?'active':''}" data-role="provider">Doctor / clinic</button></div><button class="icon-btn" data-action="notifications" aria-label="Notifications">♧</button></div></header><main class="main">${pageContent(p)}</main></section></div><nav class="mobile-nav">${nav.slice(0,4).map(([id,ic,l])=>`<button data-page="${id}" class="${S.page===id?'active':''}"><span>${ic}</span>${l.split(' ')[0]}</button>`).join('')}<button data-action="more"><span>···</span>More</button></nav>`;bind()}
function pageTitle(){const all=[...patientNav,...providerNav];return all.find(x=>x[0]===S.page)?.[2]||'Overview'}
function messageRows(p){return (p.messages||[]).filter(m=>m.visibility==='shared').map(m=>`<article class="message-row ${m.role==='patient'?'patient':''}"><div class="message-bubble"><div class="message-meta"><b>${esc(m.by)}</b><span>${esc(m.date)}</span><span class="message-kind">${m.kind==='review'?'Clinician review':m.kind==='care_update'?'Care update':'Message'}</span></div><p>${esc(m.text)}</p></div></article>`).join('')||`<div class="empty">No shared messages yet. Messages and clinician-approved updates will appear here.</div>`}
function sharedMessagesPanel(p,provider=false){return `<section class="panel">${panelTitle(provider?'Messages & shared care updates':'Messages & care updates',provider?'Visible to the patient in their Pulse history.':'A dated history of your questions and clinician-approved updates.')}<div class="message-thread">${messageRows(p)}</div>${provider?`<button class="button secondary small" style="margin-top:12px" data-action="send-update">✉ Send patient update</button>`:`<button class="button secondary small" style="margin-top:12px" data-action="ask-doctor">＋ Message my care team</button>`}</section>`}
function messagesPreview(p){const list=(p.messages||[]).filter(m=>m.visibility==='shared');const m=list[list.length-1];return `<section class="panel">${panelTitle('Messages & care updates','Shared reviews, replies and care-plan changes',`<button class="button link small" data-page="messages">View history →</button>`)}${m?`<div class="message-preview"><b>${esc(m.by)} · ${esc(m.kind==='review'?'Clinician review':m.kind==='care_update'?'Care update':'Message')}</b><p>${esc(m.text)}</p><span class="subtle">${esc(m.date)}</span></div>`:`<div class="empty">Your shared care updates will appear here.</div>`}</section>`}
function messagesPage(p){return `${heading('Your care team, in one place','Messages & care updates','See what you shared, what your clinician reviewed, and the next steps.','<button class="button" data-action="ask-doctor">＋ Message my care team</button>')}<div class="notice" style="margin-bottom:14px">Clinician reviews and care updates shown here are shared with you. Private care-team notes are not included.</div><section class="panel">${panelTitle('Shared history','Messages, reviews and care-plan updates · newest activity at the bottom')}<div class="message-thread">${messageRows(p)}</div><div class="subtle" style="margin-top:14px">Demo only: messages stay in this browser and are not sent to your clinic.</div></section>`}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${action}</div></div>`}
function panelTitle(title,desc='',right=''){return `<div class="panel-title"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${right}</div>`}
function metric(label,value,unit,foot,icon='✦',warn=false){return `<section class="panel metric"><div class="metric-icon">${icon}</div><div class="metric-label">${label}</div><div class="metric-value">${value}<span>${unit||''}</span></div><div class="metric-foot ${warn?'warn':''}">${foot}</div></section>`}
function healthOutcome(p){const start=p.trend[0]??'—',latest=p.trend.at(-1)??'—',change=Number(start)-Number(latest),movement=Number.isFinite(change)?`${change>=0?'↓':'↑'} ${Math.abs(change)} mmHg`:'Not enough readings';return `<section class="panel health-outcome"><div class="outcome-kicker"><span>♥</span> NORTH STAR · HEALTH OUTCOME</div><div class="outcome-layout"><div class="outcome-copy"><h2>Health improvement is the goal.</h2><p>Care-plan engagement is a supporting signal. We track the health outcome your clinician can review.</p><div class="outcome-comparison"><div><small>Start of sample period</small><b>${start}<span> mmHg</span></b></div><div class="outcome-change">${movement}</div><div><small>Latest systolic sample</small><b>${latest}<span> mmHg</span></b></div></div></div><div class="outcome-target"><small>Clinician-set BP target</small><strong>${esc(p.bpTarget)} mmHg</strong><p>These are illustrative readings. Your clinician interprets the trend and decides next steps.</p><button class="button secondary small" data-page="history">View BP history →</button></div></div><div class="outcome-footer"><b>What to do:</b> Keep following your doctor-defined plan and review this trend with your care team.</div></section>`}
function clinicOutcomeBanner(){return `<section class="panel health-outcome clinic-outcome"><div class="outcome-kicker"><span>♥</span> NORTH STAR · CLINICAL OUTCOME</div><div class="outcome-layout"><div class="outcome-copy"><h2>Health outcomes are the success measure.</h2><p>Track clinician-reviewed change in systolic BP over the defined care period. App engagement helps explain execution; it is not proof of health impact.</p></div><div class="outcome-target"><small>Current demo cohort</small><strong>Outcome review needed</strong><p>Sample readings are illustrative. Review patient-level trends against clinician-set targets before reporting impact.</p><button class="button secondary small" data-page="reports">View outcome measures →</button></div></div></section>`}
function pill(text,type=''){return `<span class="pill ${type}"><i class="dot"></i>${text}</span>`}
function chart(values,opts={}){const w=540,h=185,left=30,right=10,top=15,bottom=25,lo=Math.min(...values)-8,hi=Math.max(...values)+8;const pts=values.map((v,i)=>{let x=left+i*(w-left-right)/(values.length-1),y=top+(hi-v)*(h-top-bottom)/(hi-lo);return [x,y,v]});const d=pts.map((q,i)=>`${i?'L':'M'} ${q[0]} ${q[1]}`).join(' '),area=`${d} L ${pts.at(-1)[0]} ${h-bottom} L ${pts[0][0]} ${h-bottom} Z`;let ys=[0,.33,.66,1].map(f=>top+f*(h-top-bottom));let labels=opts.labels||['Oct 08','Oct 10','Oct 12','Oct 14'];return `<div class="chart-box"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Blood pressure trend chart"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#60b492" stop-opacity=".32"/><stop offset="100%" stop-color="#60b492" stop-opacity="0"/></linearGradient></defs>${ys.map(y=>`<line class="chart-grid" x1="${left}" y1="${y}" x2="${w-right}" y2="${y}"/>`).join('')}<path class="chart-area" d="${area}"/><path class="chart-line" d="${d}"/>${pts.map((q,i)=>`<circle class="chart-dot ${i===pts.length-1?'latest':''}" cx="${q[0]}" cy="${q[1]}" r="${i===pts.length-1?4:2.7}"><title>${q[2]} mmHg</title></circle>`).join('')}${labels.map((t,i)=>`<text class="chart-label" x="${left+i*(w-left-right)/(labels.length-1)}" y="${h-5}" text-anchor="${i===0?'start':i===labels.length-1?'end':'middle'}">${t}</text>`).join('')}</svg></div>`}
function weekChart(){const a=[42,51,49,68,74,71,76];return `<div style="height:150px;display:flex;align-items:end;gap:10px;padding:18px 5px 0;border-bottom:1px solid var(--line);background:repeating-linear-gradient(to bottom,transparent 0 34px,#edf1ee 35px 36px)">${a.map((v,i)=>`<div style="height:${v}%;flex:1;border-radius:7px 7px 0 0;background:${i<2?'#edb294':'#71c29e'};position:relative"><small style="position:absolute;top:-16px;left:50%;transform:translateX(-50%);font-size:8px;color:var(--muted)">${v}%</small></div>`).join('')}</div><div style="display:flex;justify-content:space-around;color:#98a49f;font-size:8px;padding-top:5px">${['W1','W2','W3','W4','W5','W6','W7'].map(x=>`<span>${x}</span>`).join('')}</div>`}
function homePage(p){const done=percent(p),tasks=S.tasks[p.id]||p.plan;return `${heading('Your care, made doable','Good morning, '+esc(p.name.split(' ')[0])+' ☀️','Your doctor’s plan, adapted to the life you actually live.','<button class="button secondary" data-page="appointments">▦ Upcoming visit</button> <button class="button" data-action="log-reading">＋ Log a reading</button>')}${healthOutcome(p)}${messagesPreview(p)}<div class="grid cols-4">${metric('Leading signal · plan execution',done,'%','↑ Improved after a routine change','▥')}${metric('Latest blood pressure',p.measurements.find(x=>x[1]==='BP')?.[2]||'No reading','mmHg','Home monitor · '+esc(p.lastSeen),'⌁')}${metric('Actions checked today',`${tasks.filter(x=>x.done).length}/${tasks.length}`,'today','Of today’s plan','✓')}${metric('Next follow-up',esc(p.appointment),'','Dr. Mehta · Swasthya Clinic','▦')}</div><div class="split" style="margin-top:15px"><div class="stack"><section class="panel">${panelTitle('Your blood pressure trend','Home readings · last 7 days',`<button class="button link small" data-page="history">View history →</button>`)}<div class="chart-legend"><span><i class="legend-dot"></i>Systolic BP</span><span class="subtle">Personal target set by your doctor: ${esc(p.bpTarget)} mmHg</span></div>${chart(p.trend)}<div class="notice">Recent home readings are for tracking and discussion with your care team. Your doctor sets the interpretation and treatment plan.</div></section><section class="panel">${panelTitle('Today’s care plan','A short list of doctor-defined actions',`<button class="button link small" data-page="plan">Full plan →</button>`)}<div class="task-list">${tasks.map(t=>taskMarkup(t,p)).join('')}</div><button class="button soft small" style="margin-top:10px" data-action="quick-complete">+ Add a one-time note</button></section></div><div class="stack"><section class="panel">${panelTitle('One thing to focus on','Context-aware support')}${p.id==='saira'&&p.engagement>=65?`<div class="insight-card"><div class="insight-mark">✦</div><div><b>Your mornings are fitting better</b><p>You told Pulse evenings can run late. Since shifting your walk to the morning, you’ve completed more of your plan. Keep the timing that works for you.</p><button class="button secondary small" data-page="insights">See how it changed</button></div></div>`:`<div class="insight-card"><div class="insight-mark">✦</div><div><b>A check-in can help us adapt</b><p>Tell Pulse what is getting in the way. Your medical plan stays with your doctor.</p><button class="button secondary small" data-page="insights">Check in</button></div></div>`}<div style="margin-top:14px" class="notice">Pulse can adjust reminders and timing. Your clinician decides what your care plan includes.</div></section><section class="panel">${panelTitle('Connected devices','Measurements sync to your timeline',`<button class="button link small" data-page="devices">Manage</button>`)}${p.devices.slice(0,2).map(d=>deviceRow(d)).join('')}</section><section class="panel">${panelTitle('Your 90-day care journey')}<div class="journey">${[['✓','Doctor sets plan','Day 0'],['✓','Pulse learns','Day 1'],['✓','You act','Week 1'],['4','Progress builds','Week 4'],['5','Doctor reviews','Day 90']].map((x,i)=>`<div class="journey-step ${i===3?'current':''}"><div class="bubble">${x[0]}</div><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div><div class="subtle">Week 4 of 13 · ${done}% of planned actions completed this week</div></section></div></div><div class="footer-note">Prototype data for demonstration · Pulse does not diagnose, prescribe, or change your treatment.</div>`}
function taskMarkup(t,p){return `<div class="task"><button class="task-check ${t.done?'done':''}" data-task="${esc(t.id)}" aria-label="${t.done?'Mark incomplete':'Mark complete'}">✓</button><div class="task-content"><b>${esc(t.title)}</b><small>${esc(t.detail||'')}</small></div><span class="task-time">${esc(t.time||'')}</span></div>`}
function planPage(p){let tasks=S.tasks[p.id]||p.plan;return `${heading('Your clinician-defined plan','Your care plan','Your doctor chooses the goals. Pulse helps fit the routine to your day.','<button class="button secondary" data-action="ask-doctor">✉ Ask my care team</button>')}<div class="grid cols-3">${metric('Care plan engagement',percent(p)+'%','this week','Actions completed so far','▥')}${metric('Plan started',esc(p.since),'','Linked to Dr. Mehta','✓')}${metric('Next review',esc(p.appointment),'','Follow-up at clinic','▦')}</div><div class="split" style="margin-top:15px"><div class="stack"><section class="panel">${panelTitle('Your actions','Mark an action complete when you have done it.',pill('Doctor-defined',''))}<div class="task-list">${tasks.map(t=>taskMarkup(t,p)).join('')}</div><hr class="section-sep"><div class="notice">Pulse may suggest a different time or reminder when routines change. It never changes the medical goal your doctor set.</div></section><section class="panel">${panelTitle('Care plan details','Set by Dr. Mehta at your consultation')}<div class="grid cols-2"><div><span class="subtle">Condition</span><p style="font-size:12px;font-weight:700;margin:5px 0">${esc(p.condition)}</p></div><div><span class="subtle">BP target</span><p style="font-size:12px;font-weight:700;margin:5px 0">${esc(p.bpTarget)} mmHg</p></div><div><span class="subtle">Activity goal</span><p style="font-size:12px;font-weight:700;margin:5px 0">As set by your doctor</p></div><div><span class="subtle">Follow-up</span><p style="font-size:12px;font-weight:700;margin:5px 0">${esc(p.appointment)}</p></div></div></section></div><div class="stack"><section class="panel">${panelTitle('Care plan progress','Weekly completion')}${weekChart()}<div class="notice" style="margin-top:15px">Completion reflects the actions recorded in Pulse. It is not a measure of your effort or character.</div></section><section class="panel">${panelTitle('Who can see this plan')}<div class="setting-row"><div><b>Your care team</b><p>Dr. Mehta · Swasthya Clinic</p></div>${pill(p.shared?'Shared':'Not shared',p.shared?'':'neutral')}</div><div class="setting-row"><div><b>Family members</b><p>You control this separately in Privacy.</p></div><button class="button secondary small" data-page="privacy">Manage</button></div></section></div></div>`}
function insightsPage(p){return `${heading('Insight → next best action','What’s getting in the way?','Pulse looks for changes in how your care plan fits everyday life.','<button class="button secondary" data-action="reset-checkin">Start a check-in</button>')}<div class="grid cols-3">${metric('Care plan engagement',percent(p)+'%','this week','Up from last week','▥')}${metric('Current routine barrier',p.id==='saira'?'Late work days':'Not shared','','You are in control of what you tell us','◷')}${metric('Adaptation status',p.id==='saira'?'Working':'Ready to check in','','Your care goals remain unchanged','✦')}</div><div class="split" style="margin-top:15px"><div class="stack"><section class="panel">${panelTitle('Your engagement over time','Planned actions completed per week')}${weekChart()}<p class="subtle" style="margin:11px 0 0">A downward pattern can start a supportive check-in. Pulse does not label this as a health deterioration.</p></section><section class="panel">${panelTitle('Your latest check-in','A routine change is a practical barrier—not a failure')}<div class="timeline-list"><div class="timeline-item"><span class="timeline-date">Week 2</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>Evening routine became difficult</b><p>You told Pulse that work was running late and evening activity was hard to fit in.</p></div></div><div class="timeline-item"><span class="timeline-date">Pulse asked</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>“What’s getting in the way?”</b><p>You chose: work schedule / timing.</p></div></div><div class="timeline-item"><span class="timeline-date">Adapted</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>Try the same activity in the morning?</b><p>Pulse proposed a timing adjustment. The doctor-defined activity goal did not change.</p></div></div><div class="timeline-item"><span class="timeline-date">This week</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>Engagement improved</b><p>${percent(p)}% of planned actions were recorded this week.</p></div></div></div></section></div><div class="stack"><section class="panel">${panelTitle('Would you like to adjust timing?','Choose a practical way to follow your current plan.')}<div class="choice-row" id="barrier-choices">${['Work schedule','Family responsibilities','Travel','Sleep or energy','Something else'].map((x,i)=>`<button class="choice ${i===0&&p.id==='saira'?'selected':''}" data-barrier="${x}">${x}</button>`).join('')}</div><div class="field" style="margin-top:12px"><label for="barrier-note">Anything you want your care team to know? (optional)</label><textarea id="barrier-note" placeholder="Share only what feels useful…"></textarea></div><button class="button" style="margin-top:12px" data-action="save-barrier">Save my check-in</button></section><section class="panel">${panelTitle('Next best action','A practical change to the routine')}<div class="insight-card"><div class="insight-mark">↗</div><div><b>Try your activity goal in the morning</b><p>Same doctor-defined activity goal, at a time that may fit better. You can change the reminder any time.</p><button class="button small" data-action="accept-adaptation">Try mornings</button> <button class="button secondary small" data-action="later-adaptation">Not now</button></div></div></section><div class="notice warn">If you feel unwell or have concerns about your condition or readings, contact your doctor or seek appropriate local care. Pulse is not an emergency service.</div></div></div>`}
function deviceRow(d){return `<div class="device-row"><div class="device-icon">${d.icon||'⌁'}</div><div class="device-meta"><b>${esc(d.name)}</b><small>${esc(d.connected?'Connected · '+d.last:d.last)}</small></div>${d.connected?pill('Connected'):pill('Not paired','neutral')}</div>`}
function devicesPage(p){return `${heading('Your devices & readings','Health data, in one place','Connect devices or record a measurement yourself. You choose what gets shared.','<button class="button" data-action="pair-device">＋ Pair a device</button>')}<div class="grid cols-3">${metric('Connected devices',p.devices.filter(d=>d.connected).length,'devices','You can disconnect at any time','⌁')}${metric('Recent BP readings',p.measurements.filter(m=>m[1]==='BP').length,'entries','From synced and manual readings','♥')}${metric('Latest sync',esc(p.lastSeen),'','Data stays on this demo browser','↻')}</div><div class="split" style="margin-top:15px"><div class="stack"><section class="panel">${panelTitle('Your connected devices','Hardware readings can flow into your care timeline',`<button class="button link small" data-action="pair-device">＋ Add</button>`)}<div class="device-list">${p.devices.map(d=>`<div class="device-row"><div class="device-icon">${d.icon}</div><div class="device-meta"><b>${esc(d.name)}</b><small>${esc(d.type)} · ${esc(d.last)}</small></div>${d.connected?`<button class="button secondary small" data-sync="${d.id}">Sync now</button>`:`<button class="button soft small" data-connect="${d.id}">Connect</button>`}<button class="button link small" data-disconnect="${d.id}" title="${d.connected?'Disconnect':'Remove'}">···</button></div>`).join('')}</div><div class="notice" style="margin-top:13px">Device connection is simulated in this prototype. No actual Bluetooth device is paired.</div></section><section class="panel">${panelTitle('Recent readings','Measurements recorded on this device',`<button class="button small" data-action="log-reading">＋ Log reading</button>`)}${readingTable(p,5)}</section></div><div class="stack"><section class="panel">${panelTitle('How data flows')}<div class="journey">${[['⌁','Home device','Cuff / meter'],['↗','Pulse app','Sync or enter'],['✦','Your timeline','Trend + context'],['◇','Your choice','Consent controls'],['⚕','Care team','Review summary']].map((x,i)=>`<div class="journey-step ${i===1?'current':''}"><div class="bubble">${x[0]}</div><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div><div class="notice">Only the signals needed to support your doctor-defined care plan should be collected.</div></section><section class="panel">${panelTitle('What can be connected?')}<div class="setting-row"><div><b>Blood pressure monitor</b><p>Supported by manual entry in this demo</p></div><span>⌁</span></div><div class="setting-row"><div><b>Glucometer</b><p>Record a reading manually in this demo</p></div><span>◉</span></div><div class="setting-row"><div><b>Phone activity</b><p>Optional signal; not required for care</p></div><span>▣</span></div></section></div></div>`}
function readingTable(p,limit=20){let rows=p.measurements.slice(0,limit);return `<div class="table-wrap"><table class="table"><thead><tr><th>Date & time</th><th>Signal</th><th>Reading</th><th>Source</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td><td><b>${esc(r[2])}</b></td><td>${esc(r[3])}</td></tr>`).join('')||`<tr><td colspan="4" class="empty">No readings yet. Log your first reading.</td></tr>`}</tbody></table></div>`}
function historyPage(p){return `${heading('Progress history','Your readings & activity','A record to help you and your doctor follow changes over time.','<button class="button secondary" data-action="export-csv">↓ Export my data</button> <button class="button" data-action="log-reading">＋ Log reading</button>')}<div class="tabs">${[['week','7 days'],['month','30 days'],['all','All activity']].map(([id,l])=>`<button data-tab="${id}" class="${S.activeTab===id?'active':''}">${l}</button>`).join('')}</div><div class="split"><div class="stack"><section class="panel">${panelTitle('Blood pressure','Systolic readings · mmHg',`<span class="subtle">Doctor-set target: ${esc(p.bpTarget)}</span>`)}${chart(p.trend)}<div class="chart-legend"><span><i class="legend-dot"></i>Systolic</span><span><i class="legend-dot peach"></i>Personal target is set by your clinician</span></div></section><section class="panel">${panelTitle('Recorded measurements','Synced and manually entered')}${readingTable(p)}</section></div><div class="stack"><section class="panel">${panelTitle('Care plan execution','Recorded actions by week')}${weekChart()}<p class="subtle" style="margin-top:12px">${percent(p)}% of this week’s planned actions marked complete.</p></section><section class="panel">${panelTitle('How to use this view')}<div class="notice">Bring this history to your appointment. A single reading does not tell the full story; your clinician interprets trends in your context.</div><hr class="section-sep"><button class="button secondary" data-page="appointments">Prepare for my visit →</button></section></div></div>`}
function appointmentsPage(p){return `${heading('Stay connected between visits','Appointments & follow-up','Your care team remains part of the loop.','<button class="button" data-action="book-appointment">＋ Request a visit</button>')}<div class="split"><div class="stack"><section class="panel">${panelTitle('Next appointment','Follow-up with your clinician')}<div class="profile-banner"><div class="device-icon" style="width:43px;height:43px;font-size:20px">▦</div><div><h2>${esc(p.appointment)}</h2><p>Dr. Mehta · Swasthya Clinic, Indore</p></div>${pill('Scheduled')}</div><div class="grid cols-2"><div><span class="subtle">Visit type</span><p style="font-size:11px;font-weight:700;margin:5px 0">Chronic care follow-up</p></div><div><span class="subtle">What to bring</span><p style="font-size:11px;font-weight:700;margin:5px 0">Recent readings & questions</p></div></div><hr class="section-sep"><button class="button secondary small" data-action="reschedule">Request a change</button></section><section class="panel">${panelTitle('Your visit prep','A concise summary for your next conversation')}<div class="setting-row"><div><b>Home BP readings</b><p>${p.measurements.filter(x=>x[1]==='BP').length} readings recorded</p></div><button class="button link small" data-page="history">Review →</button></div><div class="setting-row"><div><b>Care plan engagement</b><p>${percent(p)}% of planned actions logged this week</p></div><button class="button link small" data-page="plan">View plan →</button></div><div class="setting-row"><div><b>Barrier / support needed</b><p>${esc(p.barrier||'No barrier shared')}</p></div><button class="button link small" data-page="insights">Edit →</button></div></section></div><div class="stack"><section class="panel">${panelTitle('October 2026','Your care calendar')}<div class="calendar-grid">${['M','T','W','T','F','S','S'].map(x=>`<span class="weekday">${x}</span>`).join('')}${Array.from({length:35},(_,i)=>{let n=i-2;let v=n>0&&n<32?n:'';return `<span class="${v===14?'appt':''}">${v}</span>`}).join('')}</div><div class="notice" style="margin-top:15px">This is a demo calendar. Visit requests do not contact a clinic.</div></section><section class="panel">${panelTitle('Care team')}<div class="profile-banner"><div class="avatar" style="background:#e7eef5;color:#4d7085">DM</div><div><h2>Dr. Mehta</h2><p>Primary clinician · Swasthya Clinic</p></div></div><button class="button secondary small" data-action="ask-doctor">✉ Draft a question</button></section></div></div>`}
function privacyPage(p){return `${heading('Your data. Your choice.','Privacy & sharing','You decide what Pulse collects and what your care team can see.','<button class="button secondary" data-action="download-data">↓ Download my data</button>')}<div class="split"><div class="stack"><section class="panel">${panelTitle('Care team sharing','Only share information that supports your care')}<div class="setting-row"><div><b>Share device readings & trends</b><p>Lets your clinician review care-related measurements between visits.</p></div>${toggleMarkup('shareTrends',S.settings.shareTrends)}</div><div class="setting-row"><div><b>Share routine barriers</b><p>Work, family, timing, or other context you choose to share.</p></div>${toggleMarkup('shareContext',S.settings.shareContext)}</div><div class="setting-row"><div><b>Share weekly care-plan summary</b><p>Actions completed, missed, or adapted in the past week.</p></div>${toggleMarkup('weeklySummary',S.settings.weeklySummary)}</div></section><section class="panel">${panelTitle('Other privacy choices')}<div class="setting-row"><div><b>Share with family</b><p>Off by default. Family does not automatically see health information.</p></div>${toggleMarkup('shareFamily',S.settings.shareFamily)}</div><div class="setting-row"><div><b>Local app lock reminder</b><p>Show a reminder to keep this device private.</p></div>${toggleMarkup('privacyLock',S.settings.privacyLock)}</div><div class="setting-row"><div><b>Pulse notifications</b><p>Care-plan reminders and check-in prompts.</p></div>${toggleMarkup('notifications',S.settings.notifications)}</div></section><div class="notice">Your control applies to this prototype browser only. A deployed demo does not have secure accounts or a production data backend. Use sample information only.</div></div><div class="stack"><section class="panel">${panelTitle('Your account data')}<div class="setting-row"><div><b>Export a copy</b><p>Download sample records in JSON format.</p></div><button class="button secondary small" data-action="download-data">Download</button></div><div class="setting-row"><div><b>Clear this browser’s demo data</b><p>Restore the original prototype records.</p></div><button class="button danger small" data-action="reset-demo">Reset</button></div></section><section class="panel">${panelTitle('What this prototype does not do')}<p class="subtle" style="line-height:1.6">No real patient accounts, identity verification, encryption service, device connection, or clinical escalation channel is configured. The sample records are stored locally in this browser only.</p></section></div></div>`}
function toggleMarkup(id,value){return `<button class="toggle ${value?'on':''}" data-setting="${id}" role="switch" aria-checked="${value}"><i></i></button>`}
function clinicPage(){let needs=S.patients.filter(p=>p.review==='Review suggested').length;return `${heading('Swasthya Clinic · Indore','Good morning, Dr. Mehta','A focused view of care-plan execution between consultations.','<button class="button secondary" data-action="export-clinic">↓ Export summary</button> <button class="button" data-action="add-patient">＋ Enroll patient</button>')}${clinicOutcomeBanner()}<div class="grid cols-4">${metric('Active patients',S.patients.length,'patients','Enrolled in a care-continuity plan','♧')}${metric('Leading signal · engagement',Math.round(S.patients.reduce((a,p)=>a+p.engagement,0)/S.patients.length)+'%','this week','Across active patients','▥')}${metric('Needs review',needs,'patients',needs?'Meaningful deviation surfaced':'No urgent review queue','⚑',needs>0)}${metric('Readings synced',S.patients.reduce((a,p)=>a+p.measurements.length,0),'entries','Sample data across enrolled patients','⌁')}</div><div class="split" style="margin-top:15px"><section class="panel">${panelTitle('Patient overview','Execution and follow-up context',`<button class="button link small" data-page="patients">All patients →</button>`)}${patientTable(S.patients.slice(0,5))}</section><div class="stack"><section class="panel">${panelTitle('Attention queue','Meaningful changes only',`<button class="button link small" data-page="reviews">View queue →</button>`)}${S.patients.filter(p=>p.review==='Review suggested').length?S.patients.filter(p=>p.review==='Review suggested').map(queueItem).join(''):`<div class="empty">No patients currently need review.<br><span class="subtle">Pulse filters routine signals to reduce alert fatigue.</span></div>`}</section><section class="panel">${panelTitle('90-day continuation','Active care journey')}<div style="display:flex;align-items:center;gap:14px"><div style="font:700 31px Manrope;color:var(--green)">79<span style="font:500 13px 'DM Sans'">%</span></div><div><b style="font-size:11px">Patients continuing</b><p class="subtle" style="margin:4px 0 0">Engaged in current care journey</p></div></div><div class="progress" style="margin:13px 0 8px"><i style="width:79%"></i></div><span class="subtle">Prototype cohort · illustrative, not a clinical result</span></section></div></div><section class="panel" style="margin-top:15px">${panelTitle('The continuity loop','Doctor sets → Pulse understands → Patient acts → Doctor reviews')}<div class="journey">${[['✓','Set a plan','Doctor-defined'],['✓','Understand','Routine context'],['✓','Support action','Adapt timing'],['✓','Measure','Execution + signals'],['5','Review','Clinical judgment']].map((x,i)=>`<div class="journey-step ${i===4?'current':''}"><div class="bubble">${x[0]}</div><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div></section>`}
function queueItem(p){return `<div class="queue-card"><div class="queue-badge">⚑</div><div style="flex:1"><b>${esc(p.name)} · ${p.age}</b><p>${esc(p.review==='Review suggested'?'Care-plan engagement declined; recent readings need clinician context.':p.review)}</p><span class="small">${esc(p.condition)} · Last sync ${esc(p.lastSeen)}</span><div style="margin-top:8px"><button class="button secondary small" data-open-patient="${p.id}">Review brief</button></div></div></div>`}
function patientTable(list){return `<div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Condition</th><th>Engagement</th><th>Latest reading</th><th>Review</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="patient-cell"><span class="avatar" style="${p.id==='saira'?'':'background:#e7eef5;color:#4c7288'}">${p.initials}</span><span><b>${esc(p.name)}</b><small>${p.age} · ${esc(p.city)}</small></span></div></td><td>${esc(p.condition)}</td><td><span class="bar-track"><i class="bar-fill ${p.engagement<50?'low':''}" style="width:${p.engagement}%"></i></span>${p.engagement}%</td><td>${esc(p.measurements.find(x=>x[1]==='BP')?.[2]||'—')}</td><td>${pill(esc(p.review),p.review==='Review suggested'?'alert':'')}</td><td><button class="button secondary small" data-open-patient="${p.id}">Open</button></td></tr>`).join('')}</tbody></table></div>`}
function patientsPage(){let list=S.patients.filter(p=>(p.name+' '+p.condition+' '+p.city).toLowerCase().includes((S.search||'').toLowerCase()));return `${heading('Continuity between visits','Your patients','Review behavior, health trends, and what Pulse has tried.','<button class="button" data-action="add-patient">＋ Enroll patient</button>')}<div class="grid cols-4">${metric('Enrolled',S.patients.length,'patients','All in your clinic','♧')}${metric('On track',S.patients.filter(p=>p.review==='On track').length,'patients','No review action suggested','✓')}${metric('Review suggested',S.patients.filter(p=>p.review==='Review suggested').length,'patients','Human review remains in your hands','⚑')}${metric('Care plans active',S.patients.length,'plans','Clinician-defined goals','☷')}</div><section class="panel" style="margin-top:15px">${panelTitle('Patient list','Search the clinic roster',`<input id="patient-search" class="search" value="${esc(S.search)}" placeholder="Search patients or condition…">`)}${patientTable(list)}</section>`}
function patientDetail(p){let done=percent(p);return `${heading('Patient brief · care continuity',esc(p.name)+'’s journey','A concise view of what changed, what Pulse tried, and what happened.','<button class="button secondary" data-action="send-update">✉ Send patient update</button> <button class="button secondary" data-action="add-note">＋ Care-team note</button> <button class="button" data-action="mark-reviewed">✓ Mark reviewed</button>')}<div class="profile-banner"><div class="avatar">${p.initials}</div><div><h2>${esc(p.name)} · ${p.age} · ${esc(p.city)}</h2><p>${esc(p.condition)} · Enrolled ${esc(p.since)} · Care team: ${esc(p.doctor)}</p></div><div class="profile-end">${pill(esc(p.review),p.review==='Review suggested'?'alert':'')}<div class="subtle" style="margin-top:5px">Last activity ${esc(p.lastSeen)}</div></div></div>${healthOutcome(p)}<div class="grid cols-4">${metric('Care-plan engagement',p.engagement,'%','Current week','▥',p.engagement<50)}${metric('Latest home BP',esc(p.measurements.find(x=>x[1]==='BP')?.[2]||'—'),'mmHg','Trend is for clinician review','♥')}${metric('Readings recorded',p.measurements.length,'entries','Synced or manually entered','⌁')}${metric('Next follow-up',esc(p.appointment),'','Clinic appointment','▦')}</div><div class="split" style="margin-top:15px"><div class="stack"><section class="panel">${panelTitle('What changed','Engagement and health signal over time')}<div class="grid cols-2"><div class="stat-box"><span class="subtle">Engagement, this week</span><div style="font:700 25px Manrope;margin:7px 0">${p.engagement}%</div><div class="progress"><i style="width:${p.engagement}%"></i></div></div><div class="stat-box"><span class="subtle">Clinical target</span><div style="font:700 16px Manrope;margin:7px 0">${esc(p.bpTarget)} <span class="subtle">mmHg</span></div><span class="subtle">Set by care team</span></div></div>${chart(p.trend)}<div class="notice">Review the readings in the patient’s clinical context. Pulse does not determine treatment changes.</div></section><section class="panel">${panelTitle('Recent readings','Device and patient-reported signals')}${readingTable(p,6)}</section></div><div class="stack"><section class="panel">${panelTitle('What Pulse learned','Patient-shared context')}<div class="notice">${esc(p.barrier||'No context shared yet. Ask the patient at the next visit.')}</div><hr class="section-sep"><b style="font-size:11px">What Pulse tried</b><p class="subtle" style="line-height:1.6;margin:6px 0">${esc(p.intervention||'No execution adaptation recorded.')}</p><b style="font-size:11px">Observed response</b><p class="subtle" style="line-height:1.6;margin:6px 0">${p.engagement>=60?'Care-plan execution improved after the timing adaptation.':'Engagement remains low; discuss practical barriers with the patient.'}</p></section>${sharedMessagesPanel(p,true)}<section class="panel">${panelTitle('Doctor-defined care plan','Pulse does not modify the treatment goal')}<div class="task-list">${(S.tasks[p.id]||p.plan).map(t=>`<div class="task"><div class="task-check ${t.done?'done':''}" style="cursor:default">✓</div><div class="task-content"><b>${esc(t.title)}</b><small>${esc(t.detail)}</small></div><span class="task-time">${esc(t.time)}</span></div>`).join('')}</div><button class="button secondary small" style="margin-top:10px" data-action="edit-selected-plan">Edit plan</button></section><section class="panel">${panelTitle('Care-team-only notes','Private notes are not visible in the patient app')}<div class="timeline-list">${(p.notes||[]).filter(n=>n.visibility==='careTeam').map(n=>`<div class="timeline-item"><span class="timeline-date">${esc(n.date)}</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>${esc(n.by)}</b><p>${esc(n.text)}</p></div></div>`).join('')||`<div class="empty">No notes added in this demo.</div>`}</div></section></div></div>`}
function carebuilderPage(){let p=current(),tasks=S.tasks[p.id]||p.plan;return `${heading('Doctor sets the destination','Care plan builder','Create or update the care plan. Patients see changes in their demo view.','<button class="button secondary" data-action="add-patient">＋ Enroll patient</button>')}<div class="split"><div class="stack"><section class="panel">${panelTitle('Select patient','Changes are saved to this browser’s demo records',`<select id="patient-select" class="search">${S.patients.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)} · ${esc(x.condition)}</option>`).join('')}</select>`)}<div class="profile-banner"><div class="avatar">${p.initials}</div><div><h2>${esc(p.name)} · ${p.age} · ${esc(p.city)}</h2><p>${esc(p.condition)}</p></div>${pill('Plan active')}</div><div class="form-grid"><div class="field"><label>Condition</label><input id="plan-condition" value="${esc(p.condition)}"></div><div class="field"><label>BP target range</label><input id="plan-target" value="${esc(p.bpTarget)}"></div><div class="field"><label>Follow-up date</label><input id="plan-followup" value="${esc(p.appointment)}"></div><div class="field"><label>Care period</label><select id="plan-period"><option>90 days</option><option>30 days</option><option>6 months</option></select></div></div><hr class="section-sep"><div class="panel-title"><div><h2>Plan actions</h2><p>Clinician sets what; Pulse can support how and when.</p></div><button class="button secondary small" data-action="add-plan-action">＋ Add action</button></div><div id="builder-actions" class="task-list">${tasks.map((t,i)=>`<div class="task"><div class="device-icon">${['⌁','↗','◉','◷'][i%4]}</div><div class="task-content"><b>${esc(t.title)}</b><small>${esc(t.detail)}</small></div><span class="task-time">${esc(t.time)}</span><button class="button link small" data-remove-plan="${esc(t.id)}">×</button></div>`).join('')}</div><button class="button" style="margin-top:16px" data-action="save-plan">Save clinician-defined plan</button></section><section class="panel">${panelTitle('Safety and scope')}<div class="notice warn">Pulse is not a prescriber. Diagnosis, medication decisions, individualized clinical thresholds, and escalation actions remain with the clinician.</div><div class="setting-row"><div><b>Patient consent to share</b><p>Current setting is controlled by the patient’s privacy preferences.</p></div>${pill(p.shared?'Active':'Not shared',p.shared?'':'neutral')}</div></section></div><div class="stack"><section class="panel">${panelTitle('Plan preview','Patient view')}<div class="notice">Your doctor has set a care plan to help support your health goals. Pulse will help you fit these actions into your routine.</div><div class="task-list" style="margin-top:9px">${tasks.map(t=>`<div class="task"><div class="checkmark" style="color:var(--green)">✓</div><div class="task-content"><b>${esc(t.title)}</b><small>${esc(t.detail)}</small></div><span class="task-time">${esc(t.time)}</span></div>`).join('')}</div></section><section class="panel">${panelTitle('After you save')}<div class="timeline-list"><div class="timeline-item"><span class="timeline-date">1</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>Patient sees the updated plan</b><p>Changes also appear in the patient dashboard in this browser.</p></div></div><div class="timeline-item"><span class="timeline-date">2</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>Pulse observes execution</b><p>Completion is tracked against actions and schedule.</p></div></div><div class="timeline-item"><span class="timeline-date">3</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>Clinician reviews meaningful changes</b><p>Pulse summarizes context for follow-up.</p></div></div></div></section></div></div>`}
function reviewsPage(){let list=S.patients.filter(p=>S.reviewFilter==='all'||(S.reviewFilter==='needs'&&p.review==='Review suggested')||(S.reviewFilter==='routine'&&p.review!=='Review suggested'));return `${heading('Human-in-the-loop care','Attention queue','Review meaningful changes with context. No autonomous clinical decisions.','<button class="button secondary" data-action="export-clinic">↓ Export review list</button>')}<div class="tabs">${[['all','All patients'],['needs','Needs review'],['routine','Routine']].map(([id,l])=>`<button data-filter="${id}" class="${S.reviewFilter===id?'active':''}">${l}</button>`).join('')}</div><div class="grid cols-3">${metric('Needs clinician review',S.patients.filter(p=>p.review==='Review suggested').length,'patients','Human review is required','⚑',true)}${metric('Routine follow-up',S.patients.filter(p=>p.review!=='Review suggested').length,'patients','No meaningful deviation flagged','✓')}${metric('Alert principle','Context','first','Escalate only meaningful changes','✦')}</div><div class="stack" style="margin-top:15px">${list.map(p=>`<section class="panel">${queueItem(p)}</section>`).join('')||`<section class="panel empty">No patients in this view.</section>`}</div>`}
function reportsPage(){const avg=Math.round(S.patients.reduce((a,p)=>a+p.engagement,0)/S.patients.length);return `${heading('Measure health improvement','Outcome reports','Execution is a leading signal; clinical outcomes and continuation complete the chain.','<button class="button secondary" data-action="export-clinic">↓ Download report</button>')}${clinicOutcomeBanner()}<div class="grid cols-4">${metric('Leading signal · care-plan execution',avg,'%','Behavior measure · not the outcome','▥')}${metric('BP trend tracked',S.patients.filter(p=>p.measurements.some(m=>m[1]==='BP')).length,'patients','Clinician reviews the trend','♥')}${metric('90-day continuation','79','%','Illustrative cohort signal','↻')}${metric('Care period','90','days','Current pilot design','▦')}</div><div class="grid cols-2" style="margin-top:15px"><section class="panel">${panelTitle('Care-plan engagement by week','Percent of planned actions recorded')}${weekChart()}<div class="notice" style="margin-top:15px">Higher execution is a leading indicator. It does not by itself prove clinical impact.</div></section><section class="panel">${panelTitle('Clinical outcomes','Clinician-validated outcomes over a defined period')}<div class="stat-box"><span class="subtle">Systolic BP change</span><div style="font:700 25px Manrope;margin:8px 0">Track over 90 days</div><span class="subtle">Baseline and follow-up values need clinical validation.</span></div><hr class="section-sep"><div class="notice warn">Demo values are illustrative. Do not present these figures as measured outcomes or causal evidence.</div></section><section class="panel">${panelTitle('Patient continuity','Engaged at day 90')}<div style="display:flex;align-items:end;gap:15px;height:130px;padding:10px 25px;border-bottom:1px solid var(--line)">${[50,55,61,68,75].map((v,i)=>`<div style="height:${v}%;flex:1;background:${i===4?'#43b98c':'#c9e8d7'};border-radius:7px 7px 0 0;position:relative"><span style="position:absolute;top:-16px;left:50%;transform:translateX(-50%);font-size:9px;color:var(--muted)">${v}%</span></div>`).join('')}</div><div class="days">${['Baseline','Day 30','Day 45','Day 60','Day 90'].map(x=>`<span>${x}</span>`).join('')}</div></section><section class="panel">${panelTitle('Causal chain')}<div class="timeline-list">${[['Execution','Did the patient complete planned actions?'],['Health outcome','Did the clinician-validated measure change?'],['Continuation','Did they stay active through 90 days?']].map((x,i)=>`<div class="timeline-item"><span class="timeline-date">0${i+1}</span><span class="timeline-line"><i></i></span><div class="timeline-text"><b>${x[0]}</b><p>${x[1]}</p></div></div>`).join('')}</div></section></div>`}
function pageContent(p){if(isProvider()){switch(S.page){case'clinic':return clinicPage();case'patients':return S.selectedDetail?patientDetail(p):patientsPage();case'reviews':return reviewsPage();case'carebuilder':return carebuilderPage();case'reports':return reportsPage();default:return clinicPage()}}switch(S.page){case'home':return homePage(p);case'messages':return messagesPage(p);case'plan':return planPage(p);case'insights':return insightsPage(p);case'devices':return devicesPage(p);case'history':return historyPage(p);case'appointments':return appointmentsPage(p);case'privacy':return privacyPage(p);default:return homePage(p)}}
function modal(title,desc,body,actions){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-action="dismiss-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${title}</h2><p>${desc}</p></div><button class="modal-x" data-action="close-modal" aria-label="Close">×</button></div>${body}<div class="modal-foot">${actions}</div></div></div>`;document.querySelector('.modal-backdrop')?.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.querySelectorAll('#modal-root [data-action="close-modal"]').forEach(b=>b.addEventListener('click',closeModal))}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function toast(msg){document.getElementById('toast-root').innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>document.getElementById('toast-root').innerHTML='',2800)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{S.selectedDetail=false;go(b.dataset.page)}));document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{S.role=b.dataset.role;S.selectedDetail=false;S.page=S.role==='patient'?'home':'clinic';save();render()}));document.querySelectorAll('[data-task]').forEach(b=>b.addEventListener('click',()=>toggleTask(b.dataset.task)));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('[data-connect]').forEach(b=>b.addEventListener('click',()=>connectDevice(b.dataset.connect)));document.querySelectorAll('[data-sync]').forEach(b=>b.addEventListener('click',()=>syncDevice(b.dataset.sync)));document.querySelectorAll('[data-disconnect]').forEach(b=>b.addEventListener('click',()=>disconnectDevice(b.dataset.disconnect)));document.querySelectorAll('[data-setting]').forEach(b=>b.addEventListener('click',()=>toggleSetting(b.dataset.setting)));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{S.activeTab=b.dataset.tab;save();render()}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{S.reviewFilter=b.dataset.filter;save();render()}));document.querySelectorAll('[data-barrier]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-barrier]').forEach(c=>c.classList.remove('selected'));b.classList.add('selected')}));document.querySelectorAll('[data-open-patient]').forEach(b=>b.addEventListener('click',()=>{S.selected=b.dataset.openPatient;S.selectedDetail=true;S.page='patients';save();render()}));document.querySelectorAll('[data-remove-plan]').forEach(b=>b.addEventListener('click',()=>removePlanAction(b.dataset.removePlan)));let search=document.getElementById('patient-search');search?.addEventListener('input',e=>{let pos=e.target.selectionStart;S.search=e.target.value;save();let pg=window.scrollY;render();let el=document.getElementById('patient-search');el?.focus();el?.setSelectionRange(pos,pos);window.scrollTo(0,pg)});document.getElementById('patient-select')?.addEventListener('change',e=>{S.selected=e.target.value;save();render()})}
function toggleTask(id){let p=current(),tasks=S.tasks[p.id]||structuredClone(p.plan),t=tasks.find(x=>x.id===id);if(!t)return;t.done=!t.done;S.tasks[p.id]=tasks;p.engagement=Math.max(0,Math.min(100,p.engagement+(t.done?5:-5)));p.lastSeen='Just now';save();render();toast(t.done?'Progress saved to your care plan.':'Action marked incomplete.')}
function toggleSetting(id){S.settings[id]=!S.settings[id];save();render();toast('Your preference was updated.')}
function connectDevice(id){let d=current().devices.find(x=>x.id===id);if(d){d.connected=true;d.last='Just connected';save();render();toast(d.name+' connected in demo mode.')}}
function disconnectDevice(id){let d=current().devices.find(x=>x.id===id);if(d){d.connected=false;d.last='Disconnected';save();render();toast('Device disconnected.')}}
function syncDevice(id){let p=current(),d=p.devices.find(x=>x.id===id);if(!d)return;if(!d.connected){toast('Connect this device first.');return}if(d.type.toLowerCase().includes('pressure'))addMeasurement(p,'BP','130 / 82','Demo BP monitor');else addMeasurement(p,'Glucose','108 mg/dL','Demo glucometer');d.last='Just now';p.lastSeen='Just now';save();render();toast('Demo reading added to your timeline.')}
function addMeasurement(p,type,value,source){let date=new Date().toLocaleString('en-IN',{month:'short',day:'2-digit',hour:'numeric',minute:'2-digit'});p.measurements.unshift([date,type,value,source]);if(type==='BP'){let n=parseInt(value);if(Number.isFinite(n))p.trend.push(n);p.trend=p.trend.slice(-12)}}
function action(type){switch(type){case'log-reading':showReadingModal();break;case'pair-device':showDeviceModal();break;case'accept-adaptation':acceptAdaptation();break;case'later-adaptation':toast('No change made. Your current plan stays the same.');break;case'save-barrier':saveBarrier();break;case'reset-checkin':document.querySelector('[data-barrier="Work schedule"]')?.click();document.getElementById('barrier-note')?.focus();break;case'quick-complete':showNoteModal();break;case'ask-doctor':showMessageModal();break;case'book-appointment':showAppointmentModal();break;case'reschedule':showAppointmentModal(true);break;case'download-data':downloadJson();break;case'export-csv':exportCsv(current());break;case'export-clinic':exportClinic();break;case'reset-demo':resetDemo();break;case'notifications':go(isProvider()?'reviews':'messages');break;case'mark-reviewed':markReviewed();break;case'add-note':showNoteModal(true);break;case'send-update':showCareUpdateModal();break;case'add-patient':showEnrollModal();break;case'add-plan-action':showPlanActionModal();break;case'save-plan':savePlan();break;case'edit-selected-plan':go('carebuilder');break;case'more':showMoreNav();break;case'menu':document.querySelector('.sidebar').style.display='flex';break;case'close-modal':closeModal();break;case'dismiss-modal':break;default:break}}
function showMoreNav(){let nav=isProvider()?providerNav:patientNav;modal('More sections','Choose where to go next.',`<div class="nav">${nav.slice(4).map(([id,icon,label])=>`<button data-modal-page="${id}" style="width:100%"><span class="nav-icon">${icon}</span>${label}</button>`).join('')||'<div class="empty">All sections are already in the main navigation.</div>'}</div>`,`<button class="button secondary" data-action="close-modal">Close</button>`);document.querySelectorAll('[data-modal-page]').forEach(b=>b.addEventListener('click',()=>{closeModal();go(b.dataset.modalPage)}))}
function showReadingModal(){modal('Log a health reading','Add a measurement to this demo patient timeline.',`<form id="reading-form" class="form-grid"><div class="field"><label for="reading-type">Reading type</label><select id="reading-type"><option>Blood pressure</option><option>Blood glucose</option></select></div><div class="field"><label for="reading-time">When</label><input type="datetime-local" id="reading-time"></div><div class="field"><label for="reading-value">Value</label><input id="reading-value" placeholder="e.g. 128 / 82" required></div><div class="field"><label for="reading-source">Source</label><select id="reading-source"><option>Manual entry</option><option>Home BP monitor</option><option>Glucometer</option></select></div><div class="field full"><span class="field-help">Record only a real measurement you want in your care history. Demo data remains in this browser.</span></div></form>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-reading">Save reading</button>`);document.getElementById('save-reading').onclick=()=>{let type=document.getElementById('reading-type').value==='Blood pressure'?'BP':'Glucose',value=document.getElementById('reading-value').value.trim();if(!value){toast('Enter a reading first.');return}addMeasurement(current(),type,value,document.getElementById('reading-source').value);current().lastSeen='Just now';save();closeModal();render();toast('Reading added to your timeline.')};}
function showDeviceModal(){modal('Connect a device','Pair a supported home device in this simulated prototype.',`<div class="form-grid"><div class="field full"><label for="new-device">Device type</label><select id="new-device"><option>Blood pressure monitor</option><option>Glucometer</option><option>Activity tracker</option></select></div><div class="field full"><label for="device-name">Device name</label><input id="device-name" placeholder="e.g. Home BP cuff"></div></div><div class="notice" style="margin-top:12px">This prototype does not use Bluetooth. It will add a simulated device card so you can explore the data flow.</div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="add-device">Add demo device</button>`);document.getElementById('add-device').onclick=()=>{let t=document.getElementById('new-device').value,name=document.getElementById('device-name').value.trim()||t;current().devices.push({id:'d'+Date.now(),name,type:t==='Blood pressure monitor'?'Blood pressure':t==='Glucometer'?'Blood glucose':'Activity',icon:t==='Glucometer'?'◉':'⌁',connected:false,last:'Not paired'});save();closeModal();render();toast('Demo device added.')}}
function showMessageModal(){modal('Message your care team','Your message appears in this demo history. It is not delivered to the clinic.',`<div class="field"><label for="message-subject">Topic</label><select id="message-subject"><option>Question about my care plan</option><option>Question about a reading</option><option>Request a follow-up</option></select></div><div class="field" style="margin-top:12px"><label for="message-body">Your question</label><textarea id="message-body" placeholder="Write your question…"></textarea></div><div class="notice" style="margin-top:11px">This is a local draft only. The prototype does not contact your clinic.</div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-message">Add to history</button>`);document.getElementById('save-message').onclick=()=>{let v=document.getElementById('message-body').value.trim();if(!v){toast('Write a question first.');return}const p=current();p.messages=p.messages||[];p.messages.push({id:'m'+Date.now(),date:new Date().toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}),by:p.name.split(' ')[0],role:'patient',kind:'message',visibility:'shared',read:true,text:v});save();closeModal();go('messages');toast('Message added to your demo history.')}}
function showAppointmentModal(reschedule=false){modal(reschedule?'Request a schedule change':'Request a follow-up','Your request is a demo only; no clinic is contacted.',`<div class="form-grid"><div class="field"><label>Preferred date</label><input type="date" id="appointment-date"></div><div class="field"><label>Visit preference</label><select id="appointment-mode"><option>In-person · Swasthya Clinic</option><option>Phone follow-up</option></select></div><div class="field full"><label>Reason for visit</label><select id="appointment-reason"><option>Routine follow-up</option><option>Discuss recent readings</option><option>Review my care plan</option></select></div></div><div class="notice" style="margin-top:12px">Appointments displayed here are sample data. Please contact your clinic directly for actual scheduling.</div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-appointment">Save demo request</button>`);document.getElementById('save-appointment').onclick=()=>{let d=document.getElementById('appointment-date').value;if(d)current().appointment=new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});save();closeModal();render();toast('Demo appointment request saved locally.')}}
function showCareUpdateModal(){modal('Send a patient update','This shared update appears in the patient’s Messages & care updates history.',`<div class="field"><label for="care-update-text">Update for the patient</label><textarea id="care-update-text" placeholder="Summarize what you reviewed, the follow-up plan, or a care-plan change…"></textarea></div><div class="notice" style="margin-top:11px">Shared updates are visible to the patient. For private documentation, use Care-team note.</div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-care-update">Share update</button>`);document.getElementById('save-care-update').onclick=()=>{const text=document.getElementById('care-update-text').value.trim();if(!text){toast('Write an update first.');return}const p=current();p.messages=p.messages||[];p.messages.push({id:'m'+Date.now(),date:new Date().toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}),by:'Dr. Mehta',role:'doctor',kind:'care_update',visibility:'shared',read:false,text});save();closeModal();render();toast('Update shared in this demo history.')}}
function showNoteModal(clinical=false){modal(clinical?'Add a clinical review note':'Add a note to your care history',clinical?'Private sample note for this patient in the demo clinic workspace.':'Add a private note to this browser’s demo record.',`<div class="field"><label for="note-text">Note</label><textarea id="note-text" placeholder="${clinical?'Document a follow-up discussion…':'What would you like to remember?'}"></textarea></div>${clinical?`<div class="notice" style="margin-top:10px">Care-team-only. Use “Send patient update” to share an approved update.</div>`:''}`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-note">Save note</button>`);document.getElementById('save-note').onclick=()=>{let text=document.getElementById('note-text').value.trim();if(!text){toast('Add note text first.');return}current().notes.unshift({date:new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}),by:clinical?'Dr. Mehta':'Patient',text,visibility:'careTeam'});save();closeModal();render();toast('Note saved in demo record.')}}
function showEnrollModal(){modal('Enroll a patient','Create an illustrative clinic record for the prototype.',`<div class="form-grid"><div class="field"><label>Patient name</label><input id="enroll-name" placeholder="Name" required></div><div class="field"><label>Age</label><input id="enroll-age" type="number" min="18" max="110" placeholder="42"></div><div class="field"><label>City</label><input id="enroll-city" value="Indore"></div><div class="field"><label>Condition</label><select id="enroll-condition"><option>Hypertension</option><option>Hypertension · early pre-diabetes</option></select></div><div class="field full"><div class="notice warn">Do not enter real patient information in this public demo. New records stay only in this browser.</div></div></div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-enroll">Create demo patient</button>`);document.getElementById('save-enroll').onclick=()=>{let name=document.getElementById('enroll-name').value.trim();if(!name){toast('Enter a patient name.');return}let p={...structuredClone(seed.patients[0]),id:'p'+Date.now(),name,initials:initials(name),age:+document.getElementById('enroll-age').value||42,city:document.getElementById('enroll-city').value||'Indore',condition:document.getElementById('enroll-condition').value,engagement:0,review:'On track',lastSeen:'Not started',trend:[140,138,136],measurements:[],plan:[],devices:[],notes:[],messages:[],appointment:'Not scheduled',since:'Today'};S.patients.push(p);S.selected=p.id;S.selectedDetail=false;S.page='patients';save();closeModal();render();toast('Demo patient enrolled.')}}
function showPlanActionModal(){modal('Add a care-plan action','Add a clinician-defined action for the selected demo patient.',`<div class="form-grid"><div class="field full"><label>Action name</label><input id="action-name" placeholder="e.g. Take a short walk"></div><div class="field"><label>Timing</label><select id="action-time"><option>Morning</option><option>Midday</option><option>Evening</option><option>Any time</option></select></div><div class="field"><label>Frequency</label><select id="action-frequency"><option>Daily</option><option>5 days per week</option><option>As discussed</option></select></div><div class="field full"><label>Patient-facing detail</label><input id="action-detail" placeholder="Practical guidance from the care team"></div></div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="save-action">Add to plan</button>`);document.getElementById('save-action').onclick=()=>{let title=document.getElementById('action-name').value.trim();if(!title){toast('Name the plan action first.');return}let tasks=S.tasks[current().id]||structuredClone(current().plan);tasks.push({id:'act'+Date.now(),title,detail:document.getElementById('action-detail').value||document.getElementById('action-frequency').value,time:document.getElementById('action-time').value,done:false,source:'Dr. Mehta'});S.tasks[current().id]=tasks;save();closeModal();render();toast('Action added. Save the care plan to apply it.')}}
function acceptAdaptation(){let p=current(),tasks=S.tasks[p.id]||structuredClone(p.plan),t=tasks.find(x=>x.id==='walk')||tasks.find(x=>/walk|activ/i.test(x.title));if(t)t.time='Morning · reminder at 6:45 AM';p.intervention='Moved activity reminder to morning with patient agreement';S.tasks[p.id]=tasks;save();render();toast('Routine updated. Your doctor’s care goal did not change.')}
function saveBarrier(){let b=document.querySelector('[data-barrier].selected')?.dataset.barrier||'No barrier selected',note=document.getElementById('barrier-note')?.value.trim()||'';current().barrier=note?`${b}: ${note}`:b;save();toast('Your check-in was saved. You control what is shared.');go('insights')}
function removePlanAction(id){let tasks=S.tasks[current().id]||structuredClone(current().plan);S.tasks[current().id]=tasks.filter(t=>t.id!==id);save();render();toast('Action removed from the unsaved plan.')}
function savePlan(){let p=current();p.condition=document.getElementById('plan-condition').value;p.bpTarget=document.getElementById('plan-target').value;p.appointment=document.getElementById('plan-followup').value;S.tasks[p.id]=S.tasks[p.id]||structuredClone(p.plan);p.plan=structuredClone(S.tasks[p.id]);p.messages=p.messages||[];p.messages.push({id:'m'+Date.now(),date:new Date().toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}),by:'Dr. Mehta',role:'doctor',kind:'care_update',visibility:'shared',read:false,text:'Your care plan was updated by Dr. Mehta. Please review the current plan and bring any questions to your next visit.'});save();render();toast('Care plan saved and update added to patient history.')}
function markReviewed(){current().review='Routine follow-up';current().notes.unshift({date:'Today',by:'Dr. Mehta',text:'Reviewed Pulse continuity brief. Follow-up remains clinician-led.'});save();render();toast('Review marked complete. Clinical decisions remain with you.')}
function exportCsv(p){let rows=[['Date','Signal','Reading','Source'],...p.measurements];let csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('pulse-readings-'+p.id+'.csv',csv,'text/csv');toast('Readings exported.')}
function exportClinic(){let rows=[['Patient','Age','Condition','Engagement','Review'],...S.patients.map(p=>[p.name,p.age,p.condition,p.engagement+'%',p.review])];download('pulse-clinic-summary.csv',rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');toast('Clinic summary exported.')}
function downloadJson(){download('pulse-demo-data.json',JSON.stringify({patient:current(),settings:S.settings},null,2),'application/json');toast('Your local demo data was downloaded.')}
function download(filename,content,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function resetDemo(){if(!confirm('Reset this browser to the original demo data? Your demo changes will be removed.'))return;localStorage.removeItem(KEY);S=structuredClone(seed);render();toast('Prototype data restored.')}
function showQuickNote(){showNoteModal(false)}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="dismiss-modal"]')&&e.target.classList.contains('modal-backdrop'))closeModal()});
window.addEventListener('storage',e=>{if(e.key===KEY){S=load();render()}});
render();
